/**
 * Writes src/projects.generated.ts (gitignored) from every projects/<name>/index.tsx.
 *   pnpm registry          (studio, render, stills and edit run it first)
 */
import fs from "fs";
import path from "path";

const ROOT = path.resolve(__dirname, "../..");
const dir = path.join(ROOT, "projects");
const names = fs.existsSync(dir)
  ? fs.readdirSync(dir).filter((n) => !n.startsWith(".") && !n.startsWith("_") && fs.existsSync(path.join(dir, n, "index.tsx"))).sort()
  : [];
const ident = (n: string, i: number) => `p${i}_${n.replace(/[^a-zA-Z0-9]/g, "_")}`;
const out = [
  "// Generated by src/scripts/registry.ts — do not edit, do not commit.",
  'import type { KlaqProject } from "./klaq";',
  ...names.map((n, i) => `import { compositions as ${ident(n, i)} } from "../projects/${n}";`),
  "",
  `export const PROJECTS: KlaqProject[] = [${names.map((n, i) => `\n  { name: ${JSON.stringify(n)}, compositions: ${ident(n, i)} },`).join("")}${names.length ? "\n" : ""}];`,
  "",
].join("\n");
const file = path.join(ROOT, "src", "projects.generated.ts");
if (!fs.existsSync(file) || fs.readFileSync(file, "utf8") !== out) fs.writeFileSync(file, out);
console.log(`registry: ${names.length} project${names.length === 1 ? "" : "s"}${names.length ? ` (${names.join(", ")})` : ""}`);
